import json

def apply_3x3_1s(grid):
    """
    Rule: For each 2 in the input grid, create a 3x3 block of 1s centered on that 2.
    The 2 itself remains 2. 3s that are part of the 3x3 block become 1s.
    0s remain 0s.
    """
    rows = len(grid)
    cols = len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Mark positions that should be 1
    ones_mask = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                # Mark 3x3 block centered on this 2
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            ones_mask[nr][nc] = True

    # Apply the mask
    for r in range(rows):
        for c in range(cols):
            if ones_mask[r][c]:
                if grid[r][c] == 2:
                    result[r][c] = 2  # 2 stays 2
                elif grid[r][c] == 3:
                    result[r][c] = 1  # 3 becomes 1
                # 0s stay 0
    return result

