def apply_transform(grid):
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]  # Deep copy

    # Find all 2 positions
    two_positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

    # Apply 3x3 around each 2 (put 1s in all 8 surrounding cells)
