        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    # If the surrounding cell is 3, it becomes 1
                    # (The 2s stay as 2s, as do 0s)
                    if result[nr][nc] == 3:
                        result[nr][nc] = 1

    return result

